package com.bemo.hr.finance.domain;
import jakarta.persistence.*;import org.hibernate.annotations.TenantId;import java.time.LocalDate;import java.util.UUID;
@Entity @Table(name="effective_master_values")
public class EffectiveMasterValue{@Id private String id;@TenantId @Column(name="app_id",nullable=false)private String appId;@Column(name="master_type",nullable=false,length=50)private String masterType;@Column(name="master_id",nullable=false,length=36)private String masterId;@Column(name="value_key",nullable=false,length=80)private String valueKey;@Column(name="value_text",nullable=false,length=1000)private String valueText;@Column(name="effective_from",nullable=false)private LocalDate effectiveFrom;@Column(name="effective_to")private LocalDate effectiveTo;@Column(name="reason",nullable=false,length=500)private String reason;@Column(name="created_by",nullable=false,length=100)private String createdBy;@Column(name="created_at",nullable=false)private long createdAt;protected EffectiveMasterValue(){}public EffectiveMasterValue(String t,String id,String k,String v,LocalDate from,LocalDate to,String reason,String actor){this.id=UUID.randomUUID().toString();masterType=t;masterId=id;valueKey=k;valueText=v;effectiveFrom=from;effectiveTo=to;this.reason=reason;createdBy=actor;}@PrePersist void pre(){createdAt=System.currentTimeMillis();}public String getId(){return id;}public String getValueText(){return valueText;}public LocalDate getEffectiveFrom(){return effectiveFrom;}public LocalDate getEffectiveTo(){return effectiveTo;}public String getReason(){return reason;}}
